 "content": "def transform(grid):
    """Decode the 18x18 field into its 6x6 array of 3x3 cells.

    Colors 0, 5, and 9 are the background/noise palette; each signal tile
    contains a marker color from the remaining palette.
    """
    h, w = len(grid), len(grid[0])
    if h % 3 or w % 3:
        raise ValueError("grid dimensions must be multiples of 3")
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            counts = {}
            for rr in range(r, r + 3):
                for cc in range(c, c + 3):
                    color = grid[rr][cc]
                    if color not in (0, 5, 9):
                        counts[color] = counts.get(color, 0) + 1
            if not counts:
                row.append(0)
            else:
                row.append(min(counts, key=lambda color: (-counts[color], color)))
        out.append(row)
    return out

